import { createEffect, createSignal, onCleanup, onMount, Show, useContext, type Component } from "solid-js";

import { ContextManager, ContextManagerEvents } from "#core/ui/context-manager/context-manager.js";
import { Layout } from "#core/ui/utilities/utilities-layout.js";
import { defineLegacyComponent, SolidAdapterContext } from "#core/ui-next/components/fxs-solid-component.js";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";
import { createEngineEvent } from "#core/ui-next/utilities/game-core-utilities.js";
import { createWindowEventSignal } from "#core/ui-next/utilities/solid-utilities.js";

import { NarrativePopupManager } from "#base/ui/narrative-event/narrative-popup-manager.js";
import { NarrativeEventPanel } from "#base/ui-next/screens/narrative-events/narrative-event-panel.jsx";
import {
	chooseNarrativeDirection,
	createSmallNarrativeEventData,
	SmallNarrativeEventChoice,
	SmallNarrativeEventData,
} from "#base/ui-next/screens/narrative-events/small-narrative-event-model.js";

import style from "#base/ui/small-narrative-event/small-narrative-event.scss?url";

const Z_PLACEMENT = { x: 0, y: 0, z: 18 };
const HideSmallNarrativesEventName = "ui-hide-small-narratives" as keyof WindowEventMap;
const PANEL_PLOT_VERTICAL_OFFSET_PX = 80;

const SmallNarrativeEventAnchor: Component = () => {
	const adapterContext = useContext(SolidAdapterContext);

	const [data, setData] = createSignal<SmallNarrativeEventData | null>(null);
	const [panelHeight, setPanelHeight] = createSignal(0);

	const localPlayerTurnEnd = createEngineEvent("LocalPlayerTurnEnd");
	const hideSmallNarratives = createWindowEventSignal(HideSmallNarrativesEventName);

	let panelRef: HTMLDivElement | undefined;
	let anchorHandle: number | null = null;
	let rafId: number | null = null;

	const closePanel = (method: UIViewChangeMethod) => {
		ContextManager.pop("small-narrative-event", { viewChangeMethod: method });
	};

	const handleClose = () => {
		NarrativePopupManager.closePopup();
		closePanel(UIViewChangeMethod.PlayerInteraction);
	};

	const handleChoiceSelected = (choice: SmallNarrativeEventChoice) => {
		const eventData = data();
		if (!eventData) return;
		if (chooseNarrativeDirection(eventData.targetStoryId, choice.key, choice.icons)) {
			// Just close the popup. If the operation is successfully applied,
			// the underlying notification is cleared by gameplay systems.
			NarrativePopupManager.closePopup();
			closePanel(UIViewChangeMethod.PlayerInteraction);
		}
	};

	const onTurnEnd = () => {
		NarrativePopupManager.closePopup();
		closePanel(UIViewChangeMethod.Automatic);
	};

	const onGlobalHide = () => {
		closePanel(UIViewChangeMethod.Automatic);
	};

	const onContextClose = (event: CustomEvent) => {
		const deactivatedElementName = event.detail.deactivatedElement.typeName;
		if (!deactivatedElementName) {
			return;
		}
		if (deactivatedElementName === "small-narrative-event") {
			waitForLayout(() => {
				NarrativePopupManager.closePopup();
				closePanel(UIViewChangeMethod.Automatic);
				engine.off(ContextManagerEvents.OnClose, onContextClose);
			});
		}
	};

	createEffect(() => {
		if (!hideSmallNarratives()) {
			return;
		}
		onGlobalHide();
	});

	createEffect(() => {
		const eventData = localPlayerTurnEnd();
		if (!eventData) {
			return;
		}
		onTurnEnd();
	});

	const registerWorldAnchor = (coords: float2) => {
		anchorHandle = WorldAnchors.RegisterFixedWorldAnchor(coords, Z_PLACEMENT);
		if (anchorHandle !== null && anchorHandle >= 0) {
			adapterContext?.rootElement.setAttribute(
				"data-bind-style-transform2d",
				`{{FixedWorldAnchors.offsetTransforms[${anchorHandle}].value}}`,
			);
		} else {
			console.error("small-narrative-event: Failed to register world anchor for coords", coords);
			anchorHandle = null;
		}
	};

	const unregisterWorldAnchor = () => {
		if (anchorHandle !== null) {
			adapterContext?.rootElement.removeAttribute("data-bind-style-transform2d");
			WorldAnchors.UnregisterFixedWorldAnchor(anchorHandle);
			anchorHandle = null;
		}
	};

	// data-bind-style-transform2d in registerWorldAnchor() provides the main
	// positioning, but this top offset is needed because window height varies
	// from story to story.
	const updateHeightOffset = () => {
		if (panelRef) {
			const h = panelRef.offsetHeight;
			if (h !== panelHeight()) {
				setPanelHeight(h);
			}
		}
		rafId = window.requestAnimationFrame(updateHeightOffset);
	};

	onMount(() => {
		// This popup exists to process one or more pending narrative events.
		// Pull the first pending item from the model and render it here.
		const eventData = createSmallNarrativeEventData();
		if (!eventData) {
			NarrativePopupManager.closePopup();
			closePanel(UIViewChangeMethod.Automatic);
			return;
		}
		setData(eventData);

		if (eventData.storyCoordinates) {
			// Pan and zoom to the story location so the popup is visible on screen.
			const worldLoc = WorldUI.getPlotLocation(
				eventData.storyCoordinates,
				{ x: 0, y: 0, z: 0 },
				PlacementMode.WATER,
			);
			Camera.lookAt(worldLoc.x, worldLoc.y + 64);
			registerWorldAnchor(eventData.storyCoordinates);
		}

		rafId = window.requestAnimationFrame(updateHeightOffset);

		engine.on(ContextManagerEvents.OnClose, onContextClose);
	});

	onCleanup(() => {
		if (rafId !== null) window.cancelAnimationFrame(rafId);
		unregisterWorldAnchor();
	});

	return (
		<Show when={data()}>
			{(data) => (
				<div
					class="absolute top-0 left-0 flex flex-col items-center w-full origin-bottom-left"
					ref={panelRef}
					style={{
						top: anchorHandle !== null ? `${-panelHeight() - PANEL_PLOT_VERTICAL_OFFSET_PX}px` : undefined,
						width: Layout.pixels(570),
					}}
				>
					<NarrativeEventPanel
						bodyText={data().bodyText}
						choices={data().choices}
						storyType={data().storyType}
						leaderCiv={data().leaderCiv}
						onChoiceSelected={handleChoiceSelected}
						onClose={handleClose}
						panelID="small-narrative-event"
					/>
				</div>
			)}
		</Show>
	);
};

defineLegacyComponent(
	"small-narrative-event",
	{
		classNames: ["small-narrative-event"],
	},
	(_attrs, _element) => {
		Input.setActiveContext(InputContext.Dual);
		return <SmallNarrativeEventAnchor />;
	},
);

ComponentRegistry.register({
	name: "SmallNarrativeEvent",
	createInstance: SmallNarrativeEventAnchor,
	styles: [style],
});
